mod solution;

fn main() {
    let cases = [
    (r#"edges=0-1:4,0-2:1,2-1:2,1-3:1,2-3:5"#, r#"0,3,1,4"#),
    (r#"edges=0-1:2,0-2:5,1-2:1"#, r#"0,2,3"#),
    (r#"
edges=0-1:2,0-2:5,1-2:1
"#, r#"0,2,3"#),
    (r#"  
edges=0-1:4,0-2:1,2-1:2,1-3:1,2-3:5
  "#, r#"0,3,1,4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS dijkstra");
}
